# -*- coding: utf-8 -*-
from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn

OUT = "docs/Технологии_и_средства_разработки_РАСигры.docx"

doc = Document()
sec = doc.sections[0]
sec.page_width = Cm(21)
sec.page_height = Cm(29.7)
sec.left_margin = Cm(3)
sec.right_margin = Cm(1.5)
sec.top_margin = Cm(2)
sec.bottom_margin = Cm(2)

style = doc.styles["Normal"]
style.font.name = "Times New Roman"
style.font.size = Pt(14)
style.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
pf = style.paragraph_format
pf.line_spacing = 1.5
pf.first_line_indent = Cm(1.25)
pf.space_after = Pt(0)
pf.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY


def p(text):
    par = doc.add_paragraph(text)
    par.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    par.paragraph_format.first_line_indent = Cm(1.25)
    par.paragraph_format.line_spacing = 1.5
    par.paragraph_format.space_after = Pt(0)
    return par


def h1(text):
    par = doc.add_paragraph()
    par.alignment = WD_ALIGN_PARAGRAPH.CENTER
    par.paragraph_format.first_line_indent = Cm(0)
    par.paragraph_format.space_before = Pt(14)
    par.paragraph_format.space_after = Pt(14)
    par.paragraph_format.line_spacing = 1.0
    par.paragraph_format.keep_with_next = True
    run = par.add_run(text)
    run.bold = True
    run.font.name = "Times New Roman"
    run.font.size = Pt(14)
    return par


title = doc.add_paragraph()
title.alignment = WD_ALIGN_PARAGRAPH.CENTER
title.paragraph_format.first_line_indent = Cm(0)
title.paragraph_format.space_after = Pt(24)
title.paragraph_format.line_spacing = 1.0
run = title.add_run("ОБОСНОВАНИЕ ВЫБОРА ТЕХНОЛОГИЙ И СРЕДСТВ РАЗРАБОТКИ")
run.bold = True
run.font.name = "Times New Roman"
run.font.size = Pt(14)

# 1
h1("1 ПЛАТФОРМА И СПОСОБ ДОРАБОТКИ")
p("Для разработки выбрана гибридная схема: интерфейс приложения выполняется на HTML5, CSS3 и JavaScript, а Android-версия представляет собой оболочку на Kotlin с WebView. Один и тот же набор веб-файлов используется и в браузере как PWA, и внутри APK. Такой подход исключает две независимые реализации интерфейса и сохраняет одинаковые сценарии, тексты, иллюстрации и озвучку на обеих платформах.")
p("Android-оболочка собрана на Kotlin 1.9.24 с Android Gradle Plugin 8.5.2 и Gradle 8.9. Компиляция и targetSdk соответствуют Android 14 (API 34), минимальная версия — Android 7 (API 24). Сборка выполняется на JDK 21, байткод приложения нацелен на Java 17. Используются AndroidX AppCompat 1.7.0, AndroidX WebKit 1.11.0 и core-ktx 1.13.1. Экран зафиксирован в портретной ориентации, интерфейс рассчитан на смартфон и планшет.")
p("Файлы интерфейса не читаются из внешнего хранилища и не скачиваются из сети. WebViewAssetLoader отдаёт их по внутреннему адресу appassets.androidplatform.net, поэтому относительные пути, fetch, localStorage и WebView работают так же, как на обычном сайте, но без разрешения INTERNET. Мост AndroidDB на Kotlin связывает JavaScript с SQLite: интерфейс вызывает getState, saveState, dbInfo и exitApp, а оболочка выполняет операции с базой и системную кнопку «Назад».")
p("Нативная разработка на Jetpack Compose или XML не выбрана, потому что потребовала бы повторно реализовать все экраны, анимации и работу с иллюстрациями, уже описанными в HTML и CSS. Flutter и React Native также не используются: они добавляют собственную среду выполнения, зависимости и увеличивают APK, тогда как WebView уже присутствует в Android и достаточен для интерфейса приложения. Для проекта важнее единый контент и офлайн-работа, чем нативные элементы управления.")
p("Веб-версия оформлена как PWA: есть manifest.webmanifest с режимом standalone и портретной ориентацией, service worker и иконки для установки на экран «Домой». Установка с офлайн-режимом возможна по HTTPS; для локальной проверки используется http://localhost. В Android service worker не нужен: те же файлы уже лежат внутри APK.")

# 2
h1("2 СРЕДСТВА РАБОТЫ С ДАННЫМИ")
p("В Android-версии данные хранятся в SQLite в базе asd_comm.db. Используется штатный SQLiteOpenHelper без Room и внешних ORM. Схема включает таблицы accounts, progress, settings и app_state. Таблица progress имеет составной первичный ключ (account_id, scenario_id) и внешний ключ на accounts с ON DELETE CASCADE, поэтому удаление ребёнка автоматически удаляет его прогресс. Для accounts хранятся имя, почта, пол, аватар, признаки регистрации и подтверждения, суммарные правильные и ошибочные ответы; для progress — звёзды, завершённость, число попыток, время последней игры и результат последней попытки.")
p("SQLite выбран как встроенное решение: он не требует сервера, отдельной СУБД и сетевого доступа, поддерживает транзакции и связи между таблицами. Для небольшого объёма данных одного устройства этого достаточно. Room не подключён: схема простая, а генерация кода и дополнительные зависимости не дают выигрыша. Хранение состояния только в JSON-файлах также отклонено: пришлось бы вручную обеспечивать целостность, каскадное удаление и одновременное обновление нескольких сущностей.")
p("Запись изменений выполняется в транзакции. Метод saveState сначала обновляет или добавляет аккаунты и их прогресс, затем удаляет строки, которых больше нет в присланном состоянии, и отдельно сохраняет настройки и идентификатор активного аккаунта. Если операция не завершилась, транзакция откатывается. Это важно для многопользовательского режима на одном устройстве: несколько детей имеют отдельные профили и прогресс, но общие настройки звука, озвучки, подсказок и анимаций.")
p("В браузере используется localStorage с ключом asd-comm-accounts-v2. Формат состояния тот же: activeId, settings и accounts, внутри каждого аккаунта — profile, progress и stats. Старый одиночный профиль asd-comm-app-v1 мигрирует при первом чтении. localStorage выбран из-за простоты и синхронного доступа; объёма в несколько мегабайт хватает, поскольку в нём хранятся только профили и небольшие записи прогресса, а не аудио и иллюстрации. Медицинские данные, диагнозы и сведения о здоровье не сохраняются.")
p("Объём контента — четыре сценария, 88 шагов, 493 реплики, 148 SVG-иллюстраций и 641 файл офлайн-кэша — не влияет на размер базы. Картинки и звук лежат в assets и кэше service worker, а SQLite хранит только изменяемое состояние. Приложение не отправляет данные во внешние сервисы, не содержит аналитики и рекламы; в Android-манифесте нет разрешения INTERNET.")

# 3
h1("3 ТЕХНОЛОГИИ ОФОРМЛЕНИЯ, ЗВУКА И ОФЛАЙНА")
p("Все иллюстрации выполнены в SVG: 18 фонов, 9 персонажей, предметы и жесты. Аватары — 12 эмодзи, которые ребёнок выбирает сам. SVG выбран вместо растровых PNG, потому что он масштабируется без потери качества, занимает немного места и позволяет менять палитру и детали в одном исходнике. Иллюстрации генерируются локально скриптами на Python и не зависят от внешних сервисов. Если файл не загрузился, интерфейс показывает эмодзи-заглушку, поэтому сценарий не ломается.")
p("Вёрстка построена на обычных HTML и CSS без React, Vue и CSS-фреймворков. Это решение избегает сборщика, лишних зависимостей и проблем с офлайн-кэшем; приложение целиком помещается в APK и кэш. Используются единая шкала отступов, ограниченная палитра, системный шрифт и адаптация под экраны 360×640 и 390×844. Анимации сведены к короткой обратной связи, поддержан режим prefers-reduced-motion, элементы управления имеют видимый фокус и размер не меньше 44 пикселей.")
p("Озвучка заранее сгенерирована в 493 MP3-файла голосом ru-RU-SvetlanaNeural через edge-tts и лежит внутри приложения. Звуковые эффекты собраны на WebAudio, а при отсутствии MP3 используется системный speechSynthesis. Такой вариант выбран вместо облачного TTS: он работает офлайн, не требует ключей и не отправляет текст реплик на сервер. Настройки позволяют отдельно отключить звук и озвучку; при паузе воспроизведение останавливается.")
p("Офлайн-режим в браузере обеспечивает service worker: он кэширует оболочку и 641 файл из assets-manifest.json, применяет cache-first для медиа и network-first для оболочки. Версия кэша задаётся вручную и сейчас равна asd-comm-v21. В Android те же файлы находятся в assets/www и отдаются WebViewAssetLoader, поэтому service worker не требуется. Для установки PWA нужен HTTPS, для локальной разработки достаточно localhost; это ограничение браузера, а не приложения.")
p("Контент собирается воспроизводимым конвейером на Python: extract-voices.py извлекает реплики, make-voices.py создаёт MP3, make-art.py — SVG и иконки, make-assets-manifest.py — список файлов, copy-web.sh копирует веб-часть в Android-проект. Скрипты не входят в APK и не нужны пользователю; они фиксируют, как получены ресурсы, и позволяют пересобрать контент после изменения сценариев.")

# 4
h1("4 ИНСТРУМЕНТЫ РАЗРАБОТКИ И ПРОВЕРКИ")
p("Основная среда разработки — IntelliJ IDEA; Android-часть открывается в Android Studio или IntelliJ с Android-плагином. Сборка ведётся через Gradle Wrapper 8.9, поэтому версия Gradle не зависит от установленной системы. Для работы используются JDK 21, Android SDK 34, build-tools 34.0.0 и эмулятор Android 14 (API 34). Контроль версий — Git; в репозитории хранятся исходники, сценарии, документация и скрипты, но не сгенерированные данные и не ключи подписи.")
p("Отладка веб-части выполняется в браузере через Chrome DevTools, а внутри Android — через удалённую отладку WebView и logcat. Для повторяемых проверок используется tools/cdp.py: он подключается к WebView по Chrome DevTools Protocol, выполняет нажатия и читает состояние DOM. Это позволяет проходить регистрацию и сценарии без ручных кликов, сравнивать результаты и делать скриншоты. Для проверки APK применяются adb, установка debug- и release-сборок, системная кнопка «Назад» и запросы к SQLite через run-as.")
p("Проверка корректности включает полное прохождение четырёх сценариев на debug- и release-сборке: «Магазин» — 21 правильный ответ и 0 ошибок, «Друг» — 17/0, «Площадка» — 14/0, «Школа» — 33/0; во всех случаях три звезды. Отдельно проверены несколько аккаунтов, сохранение прогресса, выход и удаление по коду, каскадное удаление прогресса, работа в авиарежиме, кнопка «Назад» и отсутствие FATAL EXCEPTION и ANR в logcat. Результаты сверяются с записями в таблицах accounts, progress и settings.")
p("Debug-сборка собирается командой assembleDebug, release — assembleRelease. Подпись release-APK выполняется через keystore.properties и ключ release.jks; без файла свойств release собирается неподписанным и годится только для проверки. Размер готового APK около 15–16 МБ, в нём 659 файлов интерфейса, иллюстраций и озвучки. Автоматизированного CI и классических unit-тестов нет: проверка построена на CDP-сценариях, adb и SQLite-запросах, что соответствует характеру DOM-приложения.")
p("Выбранные средства обеспечивают полный цикл: разработку интерфейса, сборку Android-приложения, генерацию контента, локальное хранение и проверку на эмуляторе. Основная сложность проекта — методика, тексты реплик и качество иллюстраций, а не выбранный стек.")

doc.save(OUT)
print("saved", OUT)
